dojo.require("dotcms.dijit.image.ImageEditor");
tinymce.PluginManager.add("doteditimage", function (editor) {
	// Found in manual QA: `editor.settings` no longer exists in TinyMCE 8. `editor.options.get()`
	// looked like the replacement but only returns a value for options registered via
	// `editor.options.register()` — arbitrary custom init keys like this one just aren't tracked
	// there. `editor.getParam(name, default)` (still present in 8.x) is the one that reads
	// straight from the raw init object regardless of registration, same as the old 4.x usage.
	const dotLanguageStrings = editor.getParam("dotLanguageStrings", {});

	function addButtons() {
		editor.ui.registry.addButton("editimage", {
			icon: "edit-image",
			text: dotLanguageStrings["edit_image"],
			onAction: function () {
				const imgNode = editor.selection.getNode().nodeName === "IMG" ?
								editor.selection.getNode() :
								editor.selection.getNode().querySelector("img")

				const attrs = {
					fieldName: imgNode.dataset.fieldName,
					inode: imgNode.dataset.inode,
					identifier: imgNode.dataset.identifier,
					saveAs: imgNode.dataset.saveas,
				};

				const ImageEditor = new dotcms.dijit.image.ImageEditor({
					editImageText: "",
					fieldName: attrs.fieldName,
					binaryFieldId: attrs.identifier,
					fieldContentletId: attrs.identifier,
					saveAsFileName: attrs.saveAs,
					inode: attrs.inode,
					activeEditor: editor,
					currentNode: editor.selection.getNode()
				});

				ImageEditor.execute();
			},
		});

		editor.ui.registry.addButton("imageProperties", {
			icon: "image-options",
			text: dotLanguageStrings["propertiesLabel"],
			onAction: function () {
				editor.execCommand('mceImage');
			},
		});
	}

	function isEditableImage(img) {
		const selectorMatched = editor.dom.is( img, "img:not([data-mce-object],[data-mce-placeholder])")
			|| editor.dom.is(img, "figure.image") ;
		return selectorMatched;
	}

	function addToolbars() {
		var toolbarItems = "alignleft aligncenter alignright | imageProperties";
		if (dotCMSHasLicense) {
			toolbarItems = "alignleft aligncenter alignright | editimage | imageProperties";
		}
		// TinyMCE 8: `editor.ui.registry.addContextToolbar(name, spec)` replaces the old
		// `editor.addContextToolbar(predicateFn, itemsString)` — predicate/items are now named
		// fields on a config object rather than positional arguments.
		editor.ui.registry.addContextToolbar("doteditimage", {
			predicate: isEditableImage,
			items: toolbarItems
		});
	}
	addToolbars();
	addButtons();
});
